SELECT c.FirstName, c.LastName, e.City
FROM Customer AS c
JOIN Employee AS e ON c.SupportRepId = e.EmployeeId;

SELECT Track.Name AS TrackName, MediaType.Name AS MediaTypeName
FROM Track
JOIN MediaType ON Track.MediaTypeId = MediaType.MediaTypeId;

SELECT e.FirstName || ' ' || e.LastName AS EmployeeName, m.FirstName AS ManagerFirstName
FROM Employee e
LEFT JOIN Employee m ON e.ReportsTo = m.EmployeeId;

SELECT BillingCountry, SUM(Total) AS TotalAmount
FROM Invoice
GROUP BY BillingCountry;
